172: /**
173:  * 완주 표시는 **전 UI 단일 정책**(`isRouteCompletion` = 98%)을 쓴다(§2.6).
174:  * 반올림 백분율 95% 로 판정하던 표시는 95~97% Ride 를 「완주」로 보여 주면서
175:  * SavedRoute 는 미완주로 남는 불일치를 만들었다.
176:  */
177: function rideCompletionDisplay(s: StoredRideSession): {
178:   label: string;
179:   isCompleted: boolean;
180:   title: string;
181: } {
182:   const r = s.completionRatio;
183:   if (typeof r !== "number" || !Number.isFinite(r)) {
184:     return { label: "—", isCompleted: false, title: "완주율 없음" };
185:   }
186:   const clamped = Math.max(0, Math.min(1, r));
187:   const pct = Math.round(clamped * 100);
188:   const isCompleted = isRouteCompletion(clamped);
189:   const label = isCompleted ? "완주" : `미완주 (${pct}%)`;
190:   const completionPct = Math.round(ROUTE_COMPLETION_RATIO_THRESHOLD * 100);
191:   const title = isCompleted
192:     ? `계획 경로 대비 ${completionPct}% 이상 주행(완주로 표시)`
193:     : `계획 경로 대비 ${pct}%`;
194:   return { label, isCompleted, title };
195: }
