613:                 {periodStats.stats.caloriesUnknownCount > 0 ? (
614:                   <span className="user-info-sheet__stat-note">
615:                     미산정 {periodStats.stats.caloriesUnknownCount}회
616:                   </span>
617:                 ) : null}
618:                 {periodHasLegacyCalories ? (
619:                   <span className="user-info-sheet__stat-note">
620:                     옛=거리환산 · 새=페달·체중
621:                   </span>
622:                 ) : null}
623:               </div>
624:             </div>
625:           </div>
626: 
627:           {/*
628:             마지막 주행 카드가 곧 「최근 주행」 목록의 입구다 — 종전에는 두 블록이 패널
629:             위아래로 갈라져 있어 스크롤해서 다른 행을 찾아 눌러야 했다.
630:           */}
631:           <button
632:             type="button"
633:             className="user-info-sheet__last-ride"
634:             aria-expanded={historyOpen}
635:             aria-controls="user-info-sheet-history-list"
636:             title="Recent rides"
637:             onClick={() => setHistoryOpen((v) => !v)}
638:           >
639:             <span className="user-info-sheet__last-ride-body">
640:               <span className="user-info-sheet__last-ride-head">
641:                 <span className="user-info-sheet__last-ride-k">마지막 주행</span>
642:                 {lastRide ? (
643:                   <span className="user-info-sheet__last-ride-when">
644:                     {formatLastRideWhenKo(lastRide.endedAt)}
645:                   </span>
646:                 ) : null}
647:               </span>
648:               {lastRide ? (
649:                 <span
650:                   className="user-info-sheet__last-ride-v rtw-numeric"
651:                   title={formatRideEndedAtKo(lastRide.endedAt)}
652:                 >
653:                   {formatRideDistanceKmNumber(lastRide.distanceMeters)} km ·{" "}
654:                   {formatElapsedFromSec(lastRide.elapsedSec)} ·{" "}
655:                   {formatSessionAvgSpeedKmh(lastRide)} km/h ·{" "}
656:                   {formatSessionCaloriesEstimate(lastRide)}
657:                 </span>
658:               ) : (
659:                 <span className="user-info-sheet__last-ride-v is-empty">없음</span>
660:               )}
661:             </span>
662:             <span className={`user-info-sheet__h-chevron ${historyOpen ? "is-open" : ""}`} aria-hidden>
663:               <ChevronRight />
664:             </span>
665:           </button>
666:         {historyOpen ? (
667:           <ul id="user-info-sheet-history-list" className="user-info-sheet__list">
668:             {props.recentSessions.length === 0 ? (
669:               <li className="user-info-sheet__empty">기록 없음</li>
670:             ) : (
671:               props.recentSessions.map((s) => {
672:                 const routeCaption = rideSessionPlacesCaption(s);
673:                 const whenLabel = formatRideEndedAtKo(s.endedAt);
674:                 const completion = rideCompletionDisplay(s);
675:                 const kmLabel = `${(s.distanceMeters / 1000).toFixed(2)} km`;
676:                 const summaryTitle = `${kmLabel}  ${whenLabel}  ${completion.label}`;
677:                 /**
678:                  * 행 액션(§3.6) — 실제 종료점이 없는 legacy Ride 는 기록만 표시한다.
679:                  * 중첩 button 을 만들지 않기 위해 요약 자체가 「지도에서 보기」 버튼이고,
680:                  * 재개·새 경로는 형제 버튼으로 둔다.
681:                  */
682:                 const actions = resolveRecentRideActions(s, props.savedRoutes ?? [], {
683:                   activeRouteId: props.activeRouteId,
684:                 });
685:                 const summaryInner = (
686:                   <>
687:                     <strong className="user-info-sheet__item-km">{kmLabel}</strong>
688:                     <span className="user-info-sheet__item-when">{whenLabel}</span>
689:                     <span
690:                       className={`user-info-sheet__item-completion ${
691:                         completion.label === "—"
692:                           ? "is-unknown"
693:                           : completion.isCompleted
694:                             ? "is-completed"
695:                             : "is-partial"
696:                       }`}
697:                       title={completion.title}
698:                     >
699:                       {completion.label}
700:                     </span>
701:                   </>
702:                 );
703:                 const showOnMap = actions.canShowOnMap && props.onShowRideOnMap;
704:                 return (
705:                   <li key={s.id} className="user-info-sheet__item">
706:                     {showOnMap ? (
707:                       <button
708:                         type="button"
709:                         className="user-info-sheet__item-summary user-info-sheet__item-summary--action"
710:                         title={`${summaryTitle} — 지도에서 보기`}
711:                         aria-label={`${kmLabel} ${whenLabel} 주행 지도에서 보기`}
712:                         onClick={() => props.onShowRideOnMap?.(s)}
713:                       >
714:                         {summaryInner}
715:                       </button>
716:                     ) : (
717:                       <div className="user-info-sheet__item-summary" title={summaryTitle}>
718:                         {summaryInner}
719:                       </div>
720:                     )}
721:                     <span className="user-info-sheet__item-route" title={routeCaption}>
722:                       {routeCaption}
723:                     </span>
724:                     {actions.resumeRouteId || actions.extendAnchor || actions.resumeBlocked ? (
725:                       <div className="user-info-sheet__item-actions">
726:                         {actions.resumeRouteId && props.onResumeRideRoute ? (
727:                           <button
728:                             type="button"
729:                             className="user-info-sheet__item-action"
730:                             title="Resume this route"
731:                             onClick={() => props.onResumeRideRoute?.(actions.resumeRouteId!)}
732:                           >
733:                             이어 달리기
734:                           </button>
735:                         ) : null}
736:                         {actions.resumeBlocked ? (
737:                           <>
738:                             <span className="user-info-sheet__item-action user-info-sheet__item-action--blocked">
739:                               이어달리기 한 경로만
740:                             </span>
741:                             {props.activeRouteId && props.onFocusActiveRoute ? (
742:                               <button
743:                                 type="button"
744:                                 className="user-info-sheet__item-action"
745:                                 title="활성 경로 확인"
746:                                 onClick={() => props.onFocusActiveRoute?.(props.activeRouteId!)}
747:                               >
748:                                 활성 경로 확인
749:                               </button>
750:                             ) : null}
751:                           </>
752:                         ) : null}
753:                         {actions.extendAnchor && props.onExtendFromRide ? (
754:                           <button
755:                             type="button"
756:                             className="user-info-sheet__item-action"
757:                             title="New route from here"
758:                             onClick={() => props.onExtendFromRide?.(actions.extendAnchor!)}
759:                           >
760:                             여기서 새 경로
761:                           </button>
762:                         ) : null}
763:                       </div>
764:                     ) : null}
765:                   </li>
766:                 );
767:               })
768:             )}
769:           </ul>
770:         ) : null}
771: 
772:         {showActionsFooter ? (
773:           <div className="user-info-sheet__actions">
774:             {showGoogleLink ? (
775:               <button
776:                 type="button"
777:                 className="user-info-sheet__btn user-info-sheet__btn--google"
778:                 disabled={props.busy}
779:                 title="Link Google account"
780:                 onClick={props.onLinkGoogle}
781:               >
782:                 <AuthGoogleMark className="user-info-sheet__google-mark" />
783:                 Google 연결
784:               </button>
785:             ) : null}
786:             {showLogout ? (
787:               confirmingLogout ? (
788:                 <div className="user-info-sheet__logout-confirm" role="group" aria-label="로그아웃 확인">
789:                   {/*
790:                     게스트 로그아웃 = 데이터 삭제(2026-10-09 Chief) — 비밀번호도 Google 계정도 없어 같은 게스트로
791:                     다시 들어올 수 없으니 실제로 지운다(App handleServiceExit). 그래서 등록(Google 연결)을 같은 자리에서 권한다.
792:                   */}
793:                   <p className="user-info-sheet__logout-confirm-copy">
794:                     {props.isGuest
795:                       ? "게스트는 로그아웃하면 모든 데이터가 삭제됩니다."
796:                       : "로그아웃하시겠습니까?"}
797:                   </p>
798:                   {props.isGuest && props.onLinkGoogle ? (
799:                     <button
800:                       type="button"
801:                       className="user-info-sheet__btn user-info-sheet__btn--google"
802:                       disabled={props.busy}
803:                       onClick={props.onLinkGoogle}
804:                     >
805:                       <AuthGoogleMark className="user-info-sheet__google-mark" />
806:                       Google 연결하고 기록 지키기
807:                     </button>
808:                   ) : null}
809:                   <div className="user-info-sheet__logout-confirm-row">
810:                     <button
811:                       type="button"
812:                       className="user-info-sheet__btn"
813:                       disabled={props.busy}
814:                       onClick={() => setConfirmingLogout(false)}
815:                     >
816:                       취소
817:                     </button>
818:                     <button
819:                       type="button"
820:                       className="user-info-sheet__btn user-info-sheet__btn--danger"
821:                       disabled={props.busy}
822:                       title="Sign out"
823:                       onClick={props.onServiceExit}
824:                     >
825:                       {props.isGuest ? "그래도 로그아웃" : "로그아웃"}
826:                     </button>
827:                   </div>
828:                 </div>
829:               ) : (
830:                 <button
831:                   type="button"
832:                   className="user-info-sheet__btn user-info-sheet__btn--danger"
833:                   disabled={props.busy}
834:                   title="Sign out"
835:                   onClick={() => setConfirmingLogout(true)}
836:                 >
837:                   로그아웃
838:                 </button>
839:               )
840:             ) : null}
841:             {showAccountDeletion ? (
842:               confirmingDeletion ? (
843:                 <div
844:                   className="user-info-sheet__logout-confirm"
845:                   role="group"
846:                   aria-label="계정 탈퇴 확인"
847:                 >
848:                   <p className="user-info-sheet__logout-confirm-copy">
849:                     계정과 내 경로·주행 기록·정복 기록·토큰이 즉시 삭제되며 되돌릴 수 없습니다.
850:                     구독 중이면 해지됩니다. 내가 등록한 퍼블릭 경로는 「탈퇴한 라이더」 이름으로
851:                     남습니다.
852:                   </p>
853:                   <label className="user-info-sheet__logout-confirm-copy">
854:                     계속하려면 「{ACCOUNT_DELETION_CONFIRM_PHRASE}」를 입력하세요
855:                     <input
856:                       type="text"
857:                       className="user-info-sheet__confirm-input"
858:                       value={deletionPhrase}
859:                       disabled={deletionBusy}
860:                       aria-label="탈퇴 확인 문구"
861:                       onChange={(e) => setDeletionPhrase(e.target.value)}
862:                     />
863:                   </label>
864:                   {deletionNote ? (
865:                     <p className="user-info-sheet__logout-confirm-copy" role="alert">
866:                       {deletionNote}
867:                     </p>
868:                   ) : null}
869:                   <div className="user-info-sheet__logout-confirm-row">
870:                     <button
871:                       type="button"
872:                       className="user-info-sheet__btn"
873:                       disabled={deletionBusy}
874:                       onClick={() => {
875:                         setConfirmingDeletion(false);
876:                         setDeletionPhrase("");
877:                         setDeletionNote(null);
878:                       }}
879:                     >
880:                       취소
881:                     </button>
882:                     <button
883:                       type="button"
884:                       className="user-info-sheet__btn user-info-sheet__btn--danger"
885:                       disabled={
886:                         deletionBusy || props.rideActive || !isDeletionConfirmPhrase(deletionPhrase)
887:                       }
888:                       title="Delete account"
889:                       onClick={() => void runAccountDeletion()}
890:                     >
891:                       {deletionBusy ? "탈퇴 처리 중…" : "탈퇴"}
892:                     </button>
893:                   </div>
894:                 </div>
895:               ) : (
896:                 <button
897:                   type="button"
898:                   className="user-info-sheet__btn user-info-sheet__btn--danger"
899:                   disabled={props.busy || props.rideActive || deletionBusy}
900:                   title={props.rideActive ? "주행 중에는 탈퇴할 수 없습니다" : "Delete account"}
901:                   onClick={() => setConfirmingDeletion(true)}
902:                 >
903:                   계정 탈퇴
904:                 </button>
905:               )
906:             ) : null}
907:           </div>
908:         ) : null}
909:         </div>
910:       </aside>
911:     </div>
912:   );
913: }

